const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const e = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 15l10 6 10-6M2 12l10 6 10-6"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zM13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4M3 16h4M17 8h4M17 16h4"/>',tool:'<path d="m14 6 4 4M3 21l8-8M15 3a6 6 0 0 0-5 9l-7 7 2 2 7-7a6 6 0 0 0 9-5l-4 2-4-4z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17v1"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M3 17v4h18v-4"/>',settings:'<path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5M8 13h8M8 17h6"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 6"/>'};
const icon = n => `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n] || icons.file}</svg>`;
const cats = {A:{name:'프로젝트 운영',icon:'folder',desc:'함께 일하는 기준과 결정을 정리합니다.'},B:{name:'작품 기획',icon:'book',desc:'창작 의도와 작품의 기준을 쌓습니다.'},C:{name:'시나리오·연출',icon:'film',desc:'회차부터 장면과 숏까지 연결합니다.'},D:{name:'제작 시스템',icon:'tool',desc:'반복할 수 있는 제작 방법을 만듭니다.'},E:{name:'제작 에셋·결과물',icon:'image',desc:'산출물과 실행·검토 기록을 관리합니다.'},F:{name:'조사·레퍼런스',icon:'search',desc:'근거와 해석, 각색과 제안을 구분합니다.'}};
const types = {document:'문서·가이드',member:'팀원·역할',task:'일정·작업',meeting:'회의록',decision:'의사결정',budget:'예산·구독',character:'인물',episode:'회차',scene:'장면',shot:'숏',tool:'AI 작업자·도구',manual:'작업 매뉴얼',technical_test:'기술 테스트',asset:'에셋·결과물',run:'생성·실행 기록',review:'검토·수정',reference:'자료 목록'};
const typeCats = {document:'A',member:'A',task:'A',meeting:'A',decision:'A',budget:'A',character:'B',episode:'C',scene:'C',shot:'C',tool:'D',manual:'D',technical_test:'D',asset:'E',run:'E',review:'E',reference:'F'};
const statuses = {draft:'초안',todo:'할 일',in_progress:'진행 중',blocked:'차단됨',pending:'검토 대기',done:'완료'};
const reviews = {not_submitted:'미제출',pending:'검토 대기',changes_requested:'수정 요청',approved:'승인됨'};
const notion = [['AI 애니메이션','3f3e38d0824b817086c4ffa35a1dd7de'],['프로젝트 운영','3f3e38d0824b8114b30fc42caa416fce'],['작품 기획','3f3e38d0824b81f38b07e626d98ada75'],['시나리오·연출','3f3e38d0824b811a8fe1e228036492d6'],['제작 시스템','3f3e38d0824b8115b964d12d375962b0'],['제작 에셋·결과물','3f3e38d0824b81a7aa0bf4c1d17fc46d'],['조사·레퍼런스','3f3e38d0824b81bfa131c63d998bf8e8'],['AI 도구 선택·실행 안내','3f3e38d0824b81c88aa5c919a3b8f66e']];
let session = null, state = null, page = 'dashboard', category = '', stageId = '', selectedId = '', listView = 'list';
let filters = {search:'',category:'',stage:'',owner:'',status:'',type:'',archived:false,sample:false};
let pendingImport = null, priorFocus = null;
const isBlocked = r => r.status==='blocked' || Boolean(r.blocked_by?.length);
const activeRecords = () => (state?.records || []).filter(r => !r.archived && !r.is_sample);
const titleOf = id => state.records.find(r => r.id === id)?.title || id;
const date = value => {if(!value)return '기록 없음';try{return new Intl.DateTimeFormat('ko-KR',{dateStyle:'short',timeStyle:'short',timeZone:state?.project?.timezone||'Asia/Seoul'}).format(new Date(value));}catch{return '확인 불가';}};
const badge = (label,tone='muted') => `<span class="badge ${tone}">${e(label)}</span>`;
const statusBadge = r => badge(statuses[r.status] || r.status, {done:'green',blocked:'red',pending:'orange',in_progress:'blue'}[r.status])+(r.status!=='blocked'&&r.blocked_by?.length?' '+badge('선행 미완료','red'):'');
const options = (obj, chosen, empty) => `${empty !== undefined ? `<option value="">${e(empty)}</option>` : ''}${Object.entries(obj).map(([v,l])=>`<option value="${e(v)}" ${v===chosen?'selected':''}>${e(l?.name || l)}</option>`).join('')}`;
const btn = (label, action, style='', ico='') => `<button type="button" class="btn ${style}" data-action="${action}">${ico ? icon(ico):''}${e(label)}</button>`;
const empty = (title,copy,action='new-record',label='첫 기록 만들기') => `<div class="empty-state"><div class="empty-icon">${icon('file')}</div><div class="empty-title">${e(title)}</div><p class="empty-copy">${e(copy)}</p>${action?btn(label,action,'secondary small','plus'):''}</div>`;
async function api(path,method='GET',body) {
  const res = await fetch(path,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':session?.csrf_token || ''}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  let data; try {data = await res.json();} catch {throw new Error('서버 응답을 읽지 못했습니다. 연결 상태를 확인하세요.');}
  if (!res.ok) {if(res.status===401 && path!=='/api/login'){session=null;renderLogin();} throw new Error(data.error?.message || data.error || data.message || `요청 실패 (${res.status})`);}
  return data;
}
function toast(message,error=false) { const el=$('#toast');el.textContent=message;el.className=`toast ${error?'toast-error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add('hidden'),5000);}
async function refresh(){state=await api('/api/state');render();}
async function boot(){try{session=await api('/api/session');if(session.authenticated) await refresh();else renderLogin();}catch(err){$('#app').innerHTML=`<div class="login-page"><div class="login-card"><h1>연결을 확인해 주세요</h1><p>${e(err.message)}</p><a class="btn primary" href="/">다시 시도</a></div></div>`;}}
function renderLogin(){
 $('#app').innerHTML=`<main class="login-page"><div class="login-card"><div class="login-brand"><span class="brand-mark">A</span><span>AI 애니메이션</span></div><div class="eyebrow">PRODUCTION WORKSPACE</div><h1>이야기를 만드는<br>모든 과정, 한곳에서.</h1><p class="login-intro">기획부터 최종 검토까지.<br>우리의 작업과 기준을 차분히 쌓는 제작 공간입니다.</p><form id="login-form"><div class="form-field"><label for="username">소유자 계정</label><input id="username" name="username" autocomplete="username" required placeholder="사용자 이름"></div><div class="form-field"><label for="password">비밀번호</label><input id="password" name="password" type="password" autocomplete="current-password" required placeholder="비밀번호"></div><p id="login-error" class="form-error" role="alert"></p><button class="btn primary" type="submit">작업 공간에 로그인 ${icon('arrow')}</button></form><p class="login-foot">소유자 전용 비공개 공간 · 외부 AI 도구 미연결<br>최초 실행 시 서버에서 소유자 계정을 설정하세요.<br><code>python3 -m app.server --init-owner 사용자이름</code></p></div><div class="login-side"><span>AI ANIMATION / STUDIO NOTES</span><p>좋은 장면은<br>명확한 기준에서<br>시작됩니다.</p><small>기획 · 제작 · 검토 · 기록</small></div></main>`;
 $('#login-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target;try{const b=$('button',form);b.disabled=true;await api('/api/login','POST',Object.fromEntries(new FormData(form)));session=await api('/api/session');await refresh();}catch(err){$('#login-error').textContent=err.message;$('button',form).disabled=false;}};
}
function navigate(target, cat='', id='') {page=target;category=cat;selectedId=id;stageId=target==='stage'?id:'';filters={search:'',category:cat,stage:'',owner:'',status:'',type:'',archived:false,sample:false};render();window.scrollTo(0,0);}
function render(){
 const active = activeRecords();
 const nav = (label,target,ico,count='',cat='')=>`<button class="nav-item ${page===target && category===cat?'active':''}" data-nav="${target}" data-category="${cat}"><span class="nav-icon">${icon(ico)}</span><span>${label}</span>${count!==''?`<span class="nav-count">${count}</span>`:''}</button>`;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><a href="#" class="brand" data-nav="dashboard"><span class="brand-mark">A</span><span>AI 애니메이션<small class="brand-sub">제작 관리 공간</small></span></a><div class="workspace-pill"><span class="project-dot"></span><span>${e(state.project.name)}</span><span class="private-mark">비공개</span></div><div class="nav-section-label">작업 공간</div>${nav('대시보드','dashboard','grid')}${nav('전체 공정','pipeline','layers')}${nav('전체 기록','records','file',active.length)}${nav('검토 대기','review','check',active.filter(r=>r.review_state==='pending').length)}<div class="nav-section-label">프로젝트 라이브러리 <span>06</span></div>${Object.entries(cats).map(([k,v])=>nav(v.name,'category',v.icon,'',k)).join('')}<div class="nav-section-label">운영</div>${nav('양식·가이드','templates','book')}${nav('가져오기·내보내기','transfer','download')}${nav('일반 설정','settings','settings')}<div class="sidebar-footer"><div><span class="connection-dot"></span> 워크스테이션 미연결</div><p>파일 패키지로 작업을 전달합니다.</p><div class="sidebar-user"><span class="avatar">${e((session.user?.name || '소').slice(0,1))}</span><span>${e(session.user?.name || '소유자')}<small>소유자 · 개인 작업 공간</small></span><button class="icon-btn" aria-label="로그아웃" data-action="logout">${icon('arrow')}</button></div></div></aside><div class="mobile-overlay hidden" id="mobile-overlay" data-action="close-menu"></div><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="탐색 메뉴 열기">${icon('menu')}</button><span>작업 공간</span><span class="crumb-sep">/</span><strong>${e(pageLabel())}</strong></div><div class="top-actions"><span class="saved-indicator"><span class="connection-dot"></span> 서버 저장</span><span class="topbar-divider"></span><span class="avatar">${e((session.user?.name || '소').slice(0,1))}</span></div></header><main class="page" id="page-content" tabindex="-1">${content()}</main></div></div>`;
 bindPage();
}
function pageLabel(){return ({dashboard:'대시보드',pipeline:'전체 공정',records:'전체 기록',review:'검토 대기',templates:'양식·가이드',transfer:'가져오기·내보내기',settings:'일반 설정',detail:types[state.records.find(r=>r.id===selectedId)?.type] || '기록 상세',stage:state.stages.find(s=>s.id===stageId)?.name || '공정 상세',category:cats[category]?.name})[page] || '작업 공간';}
function heading(title,copy,actions='',eyebrow='PRODUCTION WORKSPACE'){return `<div class="page-header"><div><div class="eyebrow">${e(eyebrow)}</div><h1 class="page-title">${e(title)}</h1><p class="page-subtitle">${e(copy)}</p></div><div class="header-actions">${actions}</div></div>`;}
function content(){switch(page){case'dashboard':return dashboard();case'pipeline':return pipeline();case'stage':return stageDetail();case'records':case'category':case'review':return recordsPage();case'detail':return recordDetail();case'templates':return templatesPage();case'transfer':return transferPage();case'settings':return settingsPage();default:return dashboard();}}
function taskRows(records,emptyTitle='아직 등록된 작업이 없습니다.',limit=5){return records.length?records.slice(0,limit).map(r=>`<button class="task-row" data-record="${e(r.id)}"><span class="row-icon">${icon(r.type==='task'?'check':'file')}</span><span class="row-main"><span class="row-title">${e(r.title)} ${r.is_sample?badge('샘플'): ''}</span><span class="row-meta">${e(types[r.type])} · ${e(r.owner || '담당 미정')}${r.due_date?' · '+e(r.due_date):''}</span></span>${statusBadge(r)}<span class="row-arrow">${icon('arrow')}</span></button>`).join(''):empty(emptyTitle,'기록을 추가하면 이곳에서 이어서 작업할 수 있습니다.','', '');}
function stageCard(s,i){const tasks=activeRecords().filter(r=>r.type==='task' && r.stage_ids?.includes(s.id));const done=tasks.filter(r=>r.status==='done' && r.review_state==='approved').length;return `<button class="stage-card" data-stage="${e(s.id)}"><div class="stage-top"><span class="stage-index">${String(i+1).padStart(2,'0')}</span>${tasks.length?badge(done===tasks.length?'완료':tasks.some(isBlocked)?'차단 있음':'진행 중',done===tasks.length?'green':'muted'):''}</div><h3 class="stage-name">${e(s.name)}</h3><p class="stage-desc">${e(s.description || s.output || '입력과 완료 기준을 정리하세요.')}</p><div class="stage-footer">${tasks.length?`<span>승인 완료 <b>${done}</b> / ${tasks.length}</span><span>${Math.round(done/tasks.length*100)}%</span>`:'<span>미착수 / 작업 미등록</span><span>—</span>'}</div><div class="progress-track"><div class="progress-fill" data-progress="${tasks.length?done/tasks.length*100:0}"></div></div></button>`;}
function dashboard(){const records=activeRecords(),tasks=records.filter(r=>r.type==='task'),pending=records.filter(r=>r.review_state==='pending'),blocked=tasks.filter(isBlocked),done=tasks.filter(r=>r.status==='done'&&r.review_state==='approved');return heading('우리의 이야기가 만들어지는 곳','아직 정해지지 않은 가능성을, 하나의 완성된 작품으로.',btn('기록 만들기','new-record','primary','plus'),state.project.name)+`<div class="project-notice"><span class="project-notice-icon">${icon('book')}</span><span><strong>프로젝트의 첫 기준을 세워보세요.</strong> 작품 설정·제작 도구·일정은 아직 미정입니다. 제안과 승인된 결정을 구분해 기록합니다.</span>${badge('기획 단계','orange')}</div><div class="stats-grid">${[['등록된 작업',tasks.length,'전체 제작 공정의 실제 작업','file'],['진행 중',tasks.filter(r=>r.status==='in_progress').length,'지금 이어갈 수 있는 작업','clock'],['검토 대기',pending.length,'사람의 명시적 검토가 필요합니다','check'],['막힌 작업',blocked.length,'선행 조건과 입력을 확인하세요','alert']].map(([l,v,s,ico],i)=>`<div class="stat-card"><div class="stat-label">${l}<span class="stat-icon stat-${i}">${icon(ico)}</span></div><div class="stat-value">${v}<small>건</small></div><div class="stat-sub">${s}</div></div>`).join('')}</div><section><div class="section-header"><div><h2>전체 제작 공정 <span class="section-count">08</span></h2><p>기획부터 납품까지, 현재 위치를 확인합니다.</p></div><button class="text-btn" data-nav="pipeline">공정 자세히 보기 ${icon('arrow')}</button></div><div class="pipeline-grid">${state.stages.map(stageCard).join('')}</div><div class="footer-note">${badge('초기 제안')} 공정은 수정할 수 있습니다. 진행률은 등록된 작업 중 검토자가 승인한 완료 작업을 기준으로 계산합니다.</div></section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>${icon('clock')} 지금 할 일</h2>${badge(tasks.filter(r=>r.status!=='done'&&!isBlocked(r)).length+'건')}</div>${taskRows(tasks.filter(r=>r.status!=='done'&&!isBlocked(r)),'첫 작업을 등록해 보세요.')}</section><section class="panel"><div class="panel-head"><h2>${icon('check')} 검토 대기</h2>${badge(pending.length+'건','orange')}</div>${taskRows(pending,'검토를 기다리는 기록이 없습니다.')}</section><section class="panel"><div class="panel-head"><h2>${icon('alert')} 막힌 작업</h2>${badge(blocked.length+'건')}</div>${taskRows(blocked,'차단된 작업이 없습니다.')}</section><section class="panel"><div class="panel-head"><h2>${icon('file')} 최근 결정</h2><button class="text-btn" data-nav="category" data-category="A">모두 보기 ${icon('arrow')}</button></div>${taskRows(records.filter(r=>r.type==='decision').reverse(),'아직 확정된 결정이 없습니다.')}</section></div><section class="panel episode-panel"><div class="panel-head"><h2>${icon('film')} 회차별 현황</h2><button class="text-btn" data-nav="category" data-category="C">회차·장면·숏 보기 ${icon('arrow')}</button></div>${records.some(r=>r.type==='episode')?taskRows(records.filter(r=>r.type==='episode')):empty('이야기가 시작될 자리를 준비했습니다.','회차 수와 길이는 미정입니다. 기획이 정리되면 회차를 등록하세요.','new-episode','회차 만들기')}</section><div class="workspace-footer"><span>AI ANIMATION · PRODUCTION MANAGEMENT</span><span>${done.length}건 승인 완료 · 소유자 전용</span></div>`;}
function pipeline(){return heading('전체 제작 공정','문서 카테고리와 공정은 별개입니다. 하나의 기록을 여러 단계에 연결할 수 있습니다.',btn('작업 만들기','new-task','primary','plus'))+`<div class="notice">${icon('layers')} ${badge('수정 가능한 초기 제안')} 각 단계를 열어 입력, 담당 역할, 완료 기준과 재작업 경로를 확인하세요.</div><div class="pipeline-grid">${state.stages.map(stageCard).join('')}</div><div class="panel mt-24"><div class="panel-head"><h2>진행률을 읽는 기준</h2></div><div class="panel-body prose">등록된 실제 작업만 집계하며, 검토자의 승인과 완료 조건을 충족한 작업을 완료로 계산합니다. 작업 미등록 단계에는 가상의 진행률을 표시하지 않습니다. 입력 버전이 바뀌면 연결된 작업과 실행 기록을 다시 검토하세요.</div></div>`;}
function stageDetail(){const s=state.stages.find(s=>s.id===stageId);if(!s)return empty('단계를 찾을 수 없습니다.','전체 공정에서 다시 선택하세요.','','');const related=activeRecords().filter(r=>r.stage_ids?.includes(s.id));return heading(s.name,'이 단계의 기준과 관련 기록을 한곳에서 확인합니다.',btn('단계 편집','edit-stage','secondary')+btn('관련 기록 만들기','new-record','primary','plus'),'전체 공정 / 초기 제안')+`<div class="stage-detail-grid">${[['입력',s.input],['담당 역할',s.role],['출력',s.output],['완료 조건',s.criteria],['다음 단계',state.stages.find(x=>x.id===s.next)?.name || '없음'],['반려·재작업 경로',state.stages.find(x=>x.id===s.rework)?.name || '없음'],['하위 작업·작업 순서',s.subtasks],['추천 도구 후보·선택 이유',s.recommended_tools]].map(([l,v])=>`<section class="panel"><div class="panel-head"><h2>${l}</h2></div><div class="panel-body prose">${e(Array.isArray(v)?v.join('\n'):v || '미정')}</div></section>`).join('')}</div><section class="panel mt-24"><div class="panel-head"><h2>관련 문서·작업·산출물·결정</h2>${badge(related.length+'건')}</div>${taskRows(related,'아직 이 단계에 연결된 기록이 없습니다.',Infinity)}</section>`;}
function filteredRecords(){return state.records.filter(r=>{if(Boolean(r.archived)!==filters.archived || Boolean(r.is_sample)!==filters.sample)return false;if(page==='category'&&r.category!==category)return false;if(page==='review'&&r.review_state!=='pending')return false;return (!filters.search||[r.title,r.content,r.purpose,r.owner,types[r.type]].join(' ').toLowerCase().includes(filters.search.toLowerCase()))&&(!filters.category||r.category===filters.category)&&(!filters.stage||r.stage_ids?.includes(filters.stage))&&(!filters.owner||r.owner===filters.owner)&&(!filters.status||(filters.status==='blocked'?isBlocked(r):r.status===filters.status))&&(!filters.type||r.type===filters.type);});}
function categoryWorkPanel(){const record=state.records.find(r=>!r.archived&&!r.is_sample&&r.type==='document'&&r.fields?.category_panel===category);return `<section class="panel category-work-panel"><div class="panel-head"><h2>${icon('book')} 카테고리 작업 기준</h2>${record?statusBadge(record):badge('작업 기준 미등록')}</div><div class="panel-body">${record?`<p class="prose">${e(record.purpose || '목적을 작성해 주세요.')}</p><div class="category-panel-meta"><span>담당자 <strong>${e(record.owner || '미정')}</strong></span><span>검토자 <strong>${e(record.reviewer || '미정')}</strong></span><span>관련 공정 <strong>${e((record.stage_ids||[]).map(id=>state.stages.find(s=>s.id===id)?.name).filter(Boolean).join(' · ') || '미연결')}</strong></span>${badge(reviews[record.review_state])}</div><button type="button" class="btn secondary small" data-record="${e(record.id)}">${icon('arrow')} 작업 패널 열기</button>`:`<p class="prose">아직 이 카테고리의 작업 기준을 등록하지 않았습니다. 목적·담당자·입력·절차·도구 후보·지시문·완료 기준을 하나의 문서로 작성하고 실제 기록과 연결하세요.</p><p class="form-help">직접 저장하기 전에는 기록이 생성되지 않습니다. 작성하는 기준 문서는 이 목록과 상세 화면에서 함께 관리됩니다.</p>${btn('카테고리 작업 기준 작성','create-category-panel','secondary small','plus')}`}</div></section>`;}

function recordsPage(){const records=filteredRecords();const title=page==='category'?cats[category].name:page==='review'?'검토 대기':'전체 기록';const desc=page==='category'?cats[category].desc:page==='review'?'생성 성공은 승인과 다릅니다. 기준에 따라 검토하고 이유를 남깁니다.':'작업과 문서, 자료를 서로 연결하며 프로젝트의 맥락을 쌓습니다.';return heading(title,desc,btn('기록 만들기','new-record','primary','plus'))+`${page==='category'?categoryWorkPanel():''}<div class="tabs"><button class="tab ${!filters.archived&&!filters.sample?'active':''}" data-data-view="real">실제 기록</button><button class="tab ${!filters.archived&&filters.sample?'active':''}" data-data-view="sample">샘플 기록</button><button class="tab ${filters.archived?'active':''}" data-archive="true">보관함</button>${category==='C'?'<button class="tab" data-action="episode-tree">회차·장면·숏 탐색</button>':''}</div><div class="toolbar"><label class="search-field">${icon('search')}<input id="search-input" aria-label="기록 검색" placeholder="기록 제목, 내용, 담당자 검색" value="${e(filters.search)}"></label><select class="filter-select" id="filter-type" aria-label="기록 유형">${options(types,filters.type,'모든 유형')}</select>${page!=='category'?`<select class="filter-select" id="filter-category" aria-label="카테고리">${options(cats,filters.category,'모든 카테고리')}</select>`:''}<select class="filter-select" id="filter-stage" aria-label="공정">${options(Object.fromEntries(state.stages.map(s=>[s.id,s.name])),filters.stage,'모든 공정')}</select><select class="filter-select" id="filter-owner" aria-label="담당자">${options(Object.fromEntries([...new Set(state.records.filter(r=>!r.archived&&Boolean(r.is_sample)===filters.sample).map(r=>r.owner).filter(Boolean))].map(x=>[x,x])),filters.owner,'모든 담당자')}</select><select class="filter-select" id="filter-status" aria-label="상태">${options(statuses,filters.status,'모든 상태')}</select></div><div class="section-header compact"><span class="result-count">${records.length}개의 기록${filters.archived?' · 보관됨':''}</span><div class="view-toggle"><button data-view="list" class="${listView==='list'?'active':''}">목록</button><button data-view="kanban" class="${listView==='kanban'?'active':''}">칸반</button></div></div><div id="records-results">${records.length?(listView==='kanban'?kanban(records):recordTable(records)):empty('등록된 기록이 없습니다.','빈 프로젝트에서 시작하세요. 문서, 작업, 회차 등 필요한 기록을 추가할 수 있습니다.')}</div>`;}
function recordTable(records){return `<div class="panel table-scroll"><table class="record-table"><thead><tr><th>제목</th><th>유형</th><th>카테고리</th><th>상태</th><th>담당자</th><th>기한</th><th>검토</th></tr></thead><tbody>${records.map(r=>`<tr><td><button class="record-title" data-record="${e(r.id)}">${icon('file')} ${e(r.title)} ${r.is_sample?badge('샘플'):''}</button><small class="record-type">${e((r.stage_ids || []).map(id=>state.stages.find(s=>s.id===id)?.name).filter(Boolean).join(' · ') || '공정 미연결')}</small></td><td>${e(types[r.type])}</td><td>${e(cats[r.category]?.name)}</td><td>${statusBadge(r)}</td><td>${e(r.owner || '미정')}</td><td>${e(r.due_date || '—')}</td><td>${badge(reviews[r.review_state] || '미제출',r.review_state==='approved'?'green':'muted')}</td></tr>`).join('')}</tbody></table></div>`;}
function kanban(records){return `<div class="kanban-grid">${Object.entries(statuses).map(([k,v])=>`<section class="kanban-column"><h3>${v}<span>${records.filter(r=>r.status===k).length}</span></h3>${records.filter(r=>r.status===k).map(r=>`<button class="kanban-card" data-record="${e(r.id)}"><span class="record-type">${e(types[r.type])}</span><strong>${e(r.title)} ${r.is_sample?badge('샘플'):''}</strong><span class="row-meta">${e(r.owner || '담당 미정')}${r.due_date?' · '+e(r.due_date):''}</span>${badge(reviews[r.review_state])}${r.blocked_by?.length?badge('선행 미완료','red'):''}</button>`).join('')}</section>`).join('')}</div>`;}
function recordDetail(){const r=state.records.find(r=>r.id===selectedId);if(!r)return empty('기록을 찾을 수 없습니다.','목록에서 다시 선택해 주세요.','','');const related=state.records.filter(x=>!x.archived&&x.id!==r.id&&((r.related_ids||[]).includes(x.id)||(x.related_ids||[]).includes(r.id)||(r.prerequisites||[]).includes(x.id)||(x.prerequisites||[]).includes(r.id)));const events=(state.events||[]).filter(x=>x.record_id===r.id || x.entity_id===r.id).slice().reverse();return heading(r.title,r.purpose || '목적과 작업 기준을 작성해 주세요.',btn('편집','edit-record','secondary')+btn(r.archived?'보관 해제':'보관','archive-record','secondary')+(r.type==='task'?btn('작업 지시 승인','approve-instructions','secondary','check')+btn('작업 패키지','export-task','primary','download'):''),`${cats[r.category]?.name} / ${types[r.type]}`)+`<div class="detail-layout"><div><section class="panel"><div class="panel-head"><h2>내용과 작업 기준</h2><div>${r.is_sample?badge('샘플'):''}${statusBadge(r)} ${badge(reviews[r.review_state],r.review_state==='approved'?'green':'muted')}${r.archived?badge('보관됨'):''}</div></div><div class="panel-body">${isBlocked(r)?`<div class="notice warning"><strong>차단됨</strong>${r.fields?.blocked_reason?' · '+e(r.fields.blocked_reason):''}${r.blocked_by?.length?'<br>미완료 선행 작업: '+r.blocked_by.map(id=>e(titleOf(id))).join(' · '):''}</div>`:''}${r.stale_inputs?.length?`<div class="notice warning">입력 버전 변경 · 재검토 필요: ${r.stale_inputs.map(id=>e(titleOf(id))).join(' · ')}</div>`:''}<div class="prose">${e(r.content || '아직 내용이 없습니다. 편집에서 작성할 수 있습니다.')}</div>${r.fields?.prompt || (r.type==='task'&&r.content)?btn('작업 지시문 복사','copy-instruction','secondary small'):''}<div class="divider"></div><div class="metadata-grid">${[['입력 자료·기준 버전',r.input_version],['완료 기준',r.acceptance],['출력 규격',r.output_spec]].map(([l,v])=>`<div class="detail-section"><h3 class="detail-label">${l}</h3><div class="prose">${e(v||'미정')}</div></div>`).join('')}</div>${Object.entries(r.fields||{}).length?`<div class="divider"></div><h3 class="detail-label">유형별 세부 정보</h3><dl class="metadata-grid">${Object.entries(r.fields).filter(([k])=>k!=='media_url').map(([k,v])=>`<div><dt class="detail-label">${e(fieldLabels[k]||k)}</dt><dd class="prose">${e(displayFieldValue(k,v))}</dd></div>`).join('')}</dl>`:''}${r.type==='asset'?assetPreview(r):''}</div></section><section class="panel"><div class="panel-head"><h2>인스턴스 체크리스트</h2><span class="row-meta">체크만으로 승인되지 않습니다.</span></div><div class="panel-body">${r.checklist?.length?`<div class="checklist">${r.checklist.map((c,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${c.done?'checked':''} ${r.archived?'disabled':''}><span>${e(c.text)}</span></label>`).join('')}</div>`:empty('등록된 체크 항목이 없습니다.','편집에서 한 줄에 하나씩 추가하세요.','','')}</div></section><section class="panel"><div class="panel-head"><h2>연결된 기록</h2>${badge(related.length+'건')}</div>${related.length?taskRows(related,undefined,Infinity):empty('연결된 기록이 없습니다.','편집에서 문서·인물·회차·장면·숏·자료를 연결할 수 있습니다.','','')}</section><section class="panel"><div class="panel-head"><h2>검토·변경 이력</h2></div><div class="panel-body">${events.length?`<div class="event-list">${events.map(ev=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${e(eventLabel(ev.action || ev.event_type || ev.kind))}</strong><p>${e(ev.reason || ev.details?.reason || '')}</p><small>${e(ev.actor || ev.user || '소유자')} · ${e(date(ev.created_at || ev.at || ev.timestamp))}</small></div></div>`).join('')}</div>`:empty('기록된 이력이 없습니다.','검토 동작의 수행자·시각·이유가 여기에 남습니다.','','')}</div></section></div><aside><section class="panel"><div class="panel-head"><h2>작업 정보</h2></div><div class="panel-body metadata-list">${[['담당자',r.owner||'미정'],['검토자',r.reviewer||'미정'],['기한',r.due_date||'미정'],['리비전',`v${r.revision}`],['관련 공정',(r.stage_ids||[]).map(id=>state.stages.find(s=>s.id===id)?.name).filter(Boolean).join(' · ')||'미연결']].map(([l,v])=>`<div><span>${l}</span><strong>${e(v)}</strong></div>`).join('')}<div><span>선행 작업</span><strong>${(r.prerequisites||[]).map(id=>`<button class="text-btn" data-record="${e(id)}">${e(titleOf(id))}</button>`).join('')||'없음'}</strong></div></div></section><section class="panel"><div class="panel-head"><h2>다음 행동</h2></div><div class="panel-body action-stack">${!r.archived?`${r.review_state!=='pending'?btn('검토 요청','review-submit','secondary','check'):btn('승인하고 완료','review-approve','primary','check')}${r.review_state==='pending'?btn('수정 요청','review-reject','secondary'):''}`:''}<p class="form-help">승인에는 검토자의 명시적 동작과 이유가 필요합니다. 실행 성공과 사람의 검토 상태는 별개입니다.</p></div></section>${r.source?.url?`<section class="panel"><div class="panel-head"><h2>원본·근거</h2></div><div class="panel-body"><a class="source-link" href="${safeURL(r.source.url)}" target="_blank" rel="noopener noreferrer">Notion 원본 보기 ${icon('external')}</a><p class="form-help">원본 ID: ${e(r.source.id||'없음')}<br>읽은 시각: ${e(date(r.source.read_at))}<br>원본 수정 시각: ${e(r.source.modified_at?date(r.source.modified_at):'확인 불가')}</p>${(r.source.warnings||[]).map(w=>`<p class="notice warning">${e(w)}</p>`).join('')}</div></section>`:''}<p class="footer-note mono">${e(r.id)}</p></aside></div>`;}
function displayFieldValue(key,value){if(key==='instruction_approval'&&value&&typeof value==='object')return `${value.actor || '소유자'} · ${date(value.at || value.created_at)}\n이유: ${value.reason || '기록 없음'}\n기준 revision: ${value.source_revision || value.revision || '기록 없음'}`;if(key==='job_state')return ({queued:'대기',running:'실행 중',succeeded:'성공',failed:'실패',cancelled:'취소',interrupted:'중단'})[value]||value;if(typeof value==='boolean')return value?'예':'아니요';return typeof value==='object'?JSON.stringify(value,null,2):value;}
async function copyInstruction(){const r=state.records.find(r=>r.id===selectedId);const text=r.fields?.prompt || r.content || '';if(!text)throw new Error('복사할 지시문이 없습니다. 먼저 내용을 작성하세요.');try{if(!navigator.clipboard?.writeText)throw new Error('unavailable');await navigator.clipboard.writeText(text);}catch{const area=document.createElement('textarea');area.value=text;area.className='clipboard-helper';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw new Error('클립보드 복사에 실패했습니다. 지시문을 직접 선택해 복사하세요.');}toast('작업 지시문을 클립보드에 복사했습니다.');}

function safeURL(value){try{const u=new URL(value,location.origin);return ['https:','http:'].includes(u.protocol)?e(u.href):'#';}catch{return '#';}}
function assetPreview(r){const f=r.fields||{};if(f.media_url?.startsWith('/api/media/') && ['image/png','image/jpeg','image/webp','image/gif'].includes(f.mime_type))return `<div class="asset-preview"><img src="${e(f.media_url)}" alt="${e(r.title)} 검토용 미디어"></div>`;if(f.media_url?.startsWith('/api/media/') && f.mime_type?.startsWith('audio/'))return `<audio controls src="${e(f.media_url)}"></audio>`;if(f.media_url?.startsWith('/api/media/') && f.mime_type?.startsWith('video/'))return `<video controls src="${e(f.media_url)}"></video>`;return `<div class="notice">${icon('image')} 메타데이터만 등록되어 미디어 미리보기가 없습니다. 선택한 검토용 미디어가 포함된 결과 패키지만 저장합니다.</div>`;}
const eventLabel = a => ({created:'기록 생성',updated:'기록 수정',instructions_approved:'작업 지시 승인',project_updated:'프로젝트 설정 변경',stage_updated:'공정 기준 변경',backup_restored:'백업 복원',migration_imported:'Notion 파일 이관', 'package.export':'작업 패키지 내보내기','package.import':'결과 패키지 가져오기',create:'기록 생성',update:'기록 수정',archive:'보관',restore:'보관 해제',submit:'검토 요청',approve:'승인 · 완료',reject:'수정 요청',review_submit:'검토 요청',review_approve:'승인 · 완료',review_reject:'수정 요청'}[a] || '기록 변경');
const fieldLabels={category_panel:'작업 기준 카테고리',blocked_reason:'차단 원인',recommended_tools:'추천 도구 후보·선택 이유',subtasks:'하위 작업·작업 순서',instruction_approval:'작업 지시 승인',fact_kind:'정보 구분',source_text:'원문·근거',interpretation:'해석·각색 근거',official_url:'공식 링크',usage:'용도',input:'입력',output:'출력',execution_mode:'실행 방식',capability_evidence:'실행 가능 근거',cost_unit:'비용 단위',terms:'이용 조건',checked_at:'확인일',test_result:'테스트 결과',adoption_state:'채택 상태',ai_role:'AI 역할 정의',manual_method:'수동 수행 방법',alternative:'대안',prompt:'복사할 작업 지시문',steps:'순서가 있는 작업 절차',handoff_to:'인수인계 대상',budget_amount:'금액',cost_kind:'금액 구분',currency:'통화',media_kind:'미디어 분류',metadata_only:'메타데이터만 있음',mime_type:'파일 형식',sha256:'SHA-256',job_state:'기술 실행 상태'};
function templatesPage(){const templates=Array.isArray(state.templates)?state.templates:Object.values(state.templates||{});return heading('양식·가이드','양식은 사용법의 제안입니다. 복제로 만든 실제 기록의 내용과 체크 상태는 서로 독립적입니다.',btn('기록 만들기','new-record','primary','plus'))+`<div class="notice">${icon('book')} ${badge('제안 템플릿','orange')} Notion 원본 양식은 아직 이관되지 않았습니다. 작품 내용은 직접 입력하고 확정합니다.</div><div class="template-grid">${templates.map(t=>`<section class="template-card"><div>${badge(types[t.type]||'작업 양식')} ${badge('제안')}</div><h2>${e(t.name || t.title)}</h2><p>${e(t.description || t.purpose || '입력·절차·완료 기준을 정리하는 양식입니다.')}</p><div class="template-meta">${t.checklist?.length||0}개 체크 항목 · 독립된 새 기록</div><button class="btn secondary" data-template="${e(t.id)}">${icon('plus')} 이 양식으로 만들기</button></section>`).join('')}</div><section class="panel mt-24"><div class="panel-head"><h2>AI 작업자와 도구 후보</h2>${badge('미채택')}</div><div class="panel-body prose">AI 작업자는 사람 계정이 아닌 역할 정의입니다. PM·조사·대본·미술·영상·음향·편집·기술 보조를 도구 기록에 제안 역할로 작성할 수 있습니다. ChatGPT, NotebookLM, ChatGPT Images, Runway, Adobe Firefly, ElevenLabs, Eleven Music, DaVinci Resolve, ComfyUI는 검토할 후보이며 가입·결제·API 연결은 이루어지지 않았습니다. 구독과 API 권한은 별개로 확인해야 합니다.</div></section>`;}
function transferPage(){return heading('가져오기·내보내기','원본을 보존하고, 기준 버전이 담긴 파일로 작업을 주고받습니다.','','DATA & HANDOFF')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>${icon('layers')} 워크스테이션 패키지</h2>${badge('미연결')}</div><div class="panel-body"><p class="prose">작업 지시를 승인한 후 상세 화면에서 작업 패키지를 내려받으세요. 최종 결과 승인과는 별개입니다. 결과 패키지는 검증과 충돌 확인을 거쳐 가져옵니다.</p><div class="notice">계약 v1 · 파일 교환 방식<br>결과 수신만으로 작업을 승인하거나 완료하지 않습니다.</div><div class="action-stack">${btn('결과 패키지 가져오기','import-package','primary','upload')}<a class="btn secondary" href="/api/handoff" download>${icon('download')} 워크스테이션 handoff 받기</a></div><p class="form-help">JSON 패키지에 선택한 소형 검토 미디어를 포함할 수 있습니다. 실제 로컬 도구 실행 기능은 없습니다.</p></div></section><section class="panel"><div class="panel-head"><h2>${icon('download')} 프로젝트 백업</h2>${badge('서버 데이터')}</div><div class="panel-body"><p class="prose">현재 프로젝트의 기록·관계·단계·검토 이력을 JSON으로 내려받습니다. 복원 전 내용을 미리 확인합니다.</p><div class="action-stack">${btn('백업 내려받기','backup','secondary','download')}${btn('백업 복원','restore-backup','secondary','upload')}</div><p class="form-help">계정 비밀번호와 세션은 백업하지 않습니다. 백업 파일은 안전한 장소에 보관하세요.</p></div></section></div><section class="panel mt-24"><div class="panel-head"><h2>${icon('book')} Notion 원본 이관</h2>${badge((state.imports||[]).some(x=>x.kind==='notion')?'파일 이관 기록 있음':'원본 미이관','orange')}</div><div class="panel-body"><div class="notice warning">Notion 연결 도구와 원본 읽기 권한을 확인할 수 없어 페이지 내용·하위 데이터베이스·관계는 아직 이관하지 않았습니다. 원본 수정·삭제·공유 변경은 하지 않습니다.</div><p class="prose">Notion에서 내보낸 Markdown 또는 CSV를 가져올 수 있습니다. 원본 링크와 원본 ID를 보존하며, 같은 원본의 재가져오기는 중복·변경 충돌을 먼저 확인합니다.</p>${btn('Markdown / CSV 가져오기','import-notion','secondary','upload')}<div class="source-grid">${notion.map(([name,id])=>`<a class="source-link" href="https://app.notion.com/p/${id}" target="_blank" rel="noopener noreferrer">${e(name)} ${icon('external')}</a>`).join('')}</div><p class="form-help">위 링크는 사용자 제공 참고 목록입니다. 실제 내용 열람·이관을 의미하지 않습니다.</p></div></section><section class="panel mt-24"><div class="panel-head"><h2>최근 가져오기 기록</h2></div><div class="panel-body">${state.imports?.length?`<div class="event-list">${state.imports.slice().reverse().map(i=>`<div class="activity-row"><div><strong>${e(i.package_id || i.filename || i.id || '가져오기')}</strong><p>${e(({notion:'Notion 파일 이관',request:'작업 패키지 내보내기',result:'결과 패키지 가져오기'})[i.kind] || '가져오기 완료')} · ${e(date(i.created_at || i.imported_at))}</p></div></div>`).join('')}</div>`:empty('아직 가져온 기록이 없습니다.','검증과 확인을 마친 가져오기만 기록됩니다.','','')}</div></section>`;}
function settingsPage(){return heading('일반 설정','작업명과 표시 시간대를 변경합니다. 작품 설정과 제작 계획은 기록에서 관리하세요.')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>프로젝트 설정</h2></div><form id="settings-form" class="panel-body"><div class="form-field"><label for="project-name">프로젝트 작업명</label><input id="project-name" name="name" required maxlength="200" value="${e(state.project.name)}"><span class="form-help">현재 관리 공간의 이름은 AI 애니메이션입니다. 기존 작품의 캐릭터·세계관·브랜딩을 사용하지 않습니다.</span></div><div class="form-field"><label for="timezone">표시 시간대</label><select id="timezone" name="timezone">${options({'Asia/Tokyo':'UTC+9 · 서울 / 도쿄','Asia/Seoul':'UTC+9 · 서울','UTC':'UTC · 협정 세계시'},state.project.timezone)}</select><span class="form-help">저장·패키지 시각은 UTC ISO 8601을 유지합니다.</span></div><div class="form-error" id="settings-error" role="alert"></div><button class="btn primary" type="submit">변경 사항 저장</button></form></section><section class="panel"><div class="panel-head"><h2>프로젝트 전환</h2></div><div class="panel-body"><div class="form-field"><label for="project-switch">현재 프로젝트</label><select id="project-switch">${options(Object.fromEntries((state.projects||[state.project]).map(p=>[p.id,p.name])),state.project.id)}</select></div>${btn('새 프로젝트 만들기','new-project','secondary','plus')}<div class="divider"></div><h3 class="detail-label">데이터 소유권과 접근</h3><p class="prose">기획·작업·검토 결정은 이 Site가 원본입니다. 파일·실행·기술 결과는 별도 워크스테이션이 원본입니다. 현재 버전은 소유자 전용이며 팀 공유와 역할별 계정 초대는 지원하지 않습니다.</p><p class="form-help">서버 SQLite 저장 · 로그인 필수 · 외부 API 키 불필요</p></div></section></div><section class="panel mt-24"><div class="panel-head"><h2>지키는 기준</h2></div><div class="panel-body prose">기획자: 영고<br>사실 / 원문 해석 / 창작자의 각색 / AI 제안은 구분해 기록합니다.<br>‘포로기’ 범위, 신학적 해석, 인물, 줄거리, 회차 수, 길이, 예산, 일정, 화풍, 도구는 아직 확정되지 않았습니다.<br>체크리스트 완료나 생성 성공을 기획자의 승인으로 취급하지 않습니다.</div></section>`;}
function modal(title,body,footer='',wide=false){priorFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'':'narrow'}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn close-btn" aria-label="닫기" data-action="close-modal">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.body.classList.add('modal-open');$('input:not([type=hidden]),textarea,button', $('#modal-root'))?.focus();}
function closeModal(){const id=priorFocus?.id;$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');if(priorFocus?.isConnected)priorFocus.focus();else if(id)$('#'+CSS.escape(id))?.focus();}
function inputField(label,name,value='',kind='text',extra=''){return `<div class="form-field"><label for="form-${name}">${label}</label>${kind==='textarea'?`<textarea id="form-${name}" name="${name}" ${/rows=/.test(extra)?'':'rows="3"'} ${extra}>${e(value)}</textarea>`:`<input id="form-${name}" name="${name}" type="${kind}" value="${e(value)}" ${extra}>`}</div>`;}
function selectField(label,name,obj,value='',multiple=false){return `<div class="form-field"><label for="form-${name}">${label}</label><select id="form-${name}" name="${name}" ${multiple?'multiple size="4"':''}>${multiple?Object.entries(obj).map(([k,v])=>`<option value="${e(k)}" ${(value||[]).includes(k)?'selected':''}>${e(v?.name || v)}</option>`).join(''):options(obj,value)}</select>${multiple?'<span class="form-help">Ctrl / Command 또는 Shift로 여러 항목 선택</span>':''}</div>`;}
function recordForm(existing=null,type='document',seed={}){
 const r=existing || {type,title:'',category:category || typeCats[type],stage_ids:stageId?[stageId]:[],status:'draft',owner:'',reviewer:'',due_date:'',content:'',purpose:'',input_version:'',prerequisites:[],related_ids:[],acceptance:'',output_spec:'',checklist:[],fields:{},...seed};
 const relationOptions=Object.fromEntries(state.records.filter(x=>!x.archived&&x.id!==r.id).map(x=>[x.id,`${types[x.type]} · ${x.title}`]));
 modal(existing?'기록 편집':'새 기록 만들기',`<form id="record-form"><div class="form-grid">${inputField('제목','title',r.title,'text','required maxlength="200"')}${selectField('기록 유형','type',types,r.type)}${selectField('카테고리','category',cats,r.category)}${selectField('현재 상태','status',Object.fromEntries(Object.entries(statuses).filter(([k])=>k!=='done'||r.status==='done')),r.status)}${inputField('담당자','owner',r.owner)}${inputField('검토자','reviewer',r.reviewer,'text',`placeholder="${e(session.user?.name || '검토자 이름')}"`)}${inputField('기한','due_date',r.due_date,'date')}${selectField('관련 공정','stage_ids',Object.fromEntries(state.stages.map(s=>[s.id,s.name])),r.stage_ids,true)}<div class="full-width">${inputField('목적','purpose',r.purpose,'textarea')}${inputField('내용·세부 작성 항목','content',r.content,'textarea','rows="7"')}${inputField('입력 자료·기준 버전','input_version',r.input_version,'textarea')}${inputField('완료·반려 기준','acceptance',r.acceptance,'textarea')}${inputField('출력 규격','output_spec',r.output_spec,'textarea')}</div>${selectField('관련 문서·인물·회차·장면·숏·에셋·자료','related_ids',relationOptions,r.related_ids,true)}${selectField('선행 작업','prerequisites',Object.fromEntries(state.records.filter(x=>!x.archived&&x.type==='task'&&x.id!==r.id).map(x=>[x.id,x.title])),r.prerequisites,true)}<div class="full-width">${inputField('체크리스트 · 한 줄에 한 항목','checklist_text',(r.checklist||[]).map(c=>c.text).join('\n'),'textarea')}<div class="notice">체크 항목은 각 기록에 독립적으로 저장됩니다. 완료·승인은 검토 동작에서 진행합니다.</div></div><div class="full-width">${selectField('기준으로 사용할 입력 기록 · revision 고정','input_record_ids',relationOptions,Object.keys(r.input_revisions||{}),true)}<label class="check-item"><input type="checkbox" name="refresh_input_revisions" value="yes">선택한 입력을 현재 revision으로 재확인</label><p class="form-help">최초 연결 시 현재 revision을 기록합니다. 입력이 바뀌면 재검토가 필요합니다. 기존 기준 버전 갱신은 확인 후 선택하세요.</p></div><div class="full-width" id="type-fields"></div></div><p class="form-error" id="record-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button class="btn primary" type="submit">${existing?'변경 사항 저장':'기록 저장'}</button></div></form>`,'',true);
 const form=$('#record-form');$('#form-type').onchange=()=>{if(!existing)$('#form-category').value=typeCats[$('#form-type').value];renderTypeFields($('#form-type').value,r.fields||{});};renderTypeFields(r.type,r.fields||{});
 form.onsubmit=async ev=>{ev.preventDefault();const save=$('[type=submit]',form);save.disabled=true;const data=Object.fromEntries(new FormData(form));for(const key of ['stage_ids','related_ids','prerequisites'])data[key]=$$('option:checked',form.elements[key]).map(o=>o.value);data.input_revisions=Object.fromEntries($$('option:checked',form.elements.input_record_ids).map(o=>[o.value,data.refresh_input_revisions==='yes'?state.records.find(x=>x.id===o.value).revision:(r.input_revisions?.[o.value] || state.records.find(x=>x.id===o.value).revision)]));delete data.input_record_ids;delete data.refresh_input_revisions;data.checklist=data.checklist_text.split('\n').map(t=>t.trim()).filter(Boolean).map(text=>({text,done:(r.checklist||[]).find(c=>c.text===text)?.done || false}));delete data.checklist_text;data.fields={...(r.fields||{})};for(const key of Object.keys(data)){if(key.startsWith('field_')){data.fields[key.slice(6)]=data[key];delete data[key];}}
 try{if(existing)data.revision=r.revision;const saved=await api(existing?'/api/records/'+encodeURIComponent(r.id):'/api/records',existing?'PATCH':'POST',data);closeModal();state=await api('/api/state');selectedId=saved.record?.id || saved.id || r.id;page='detail';render();toast('서버에 저장했습니다.');}catch(err){$('#record-error').textContent=err.message;save.disabled=false;}};
}
function renderTypeFields(type,fields){let keys=['steps','prompt','alternative','manual_method','handoff_to'];if(type==='task')keys=['blocked_reason',...keys];if(type==='reference'||type==='document'||type==='character'||type==='episode')keys=['fact_kind','source_text','interpretation',...keys];if(type==='tool')keys=['ai_role','official_url','usage','input','output','execution_mode','capability_evidence','alternative','cost_unit','terms','checked_at','test_result','adoption_state','prompt','manual_method'];if(type==='budget')keys=['budget_amount','currency','cost_kind','source_text'];if(type==='asset')keys=['media_kind','mime_type','sha256','source_text'];if(type==='run')keys=['job_state','cost_kind','budget_amount','source_text'];$('#type-fields').innerHTML=`<details open><summary class="detail-label">유형별 세부 정보 · ${e(types[type])}</summary><div class="form-grid">${keys.map(k=>['fact_kind','cost_kind','adoption_state','execution_mode','media_kind','job_state'].includes(k)?selectField(fieldLabels[k]||k,'field_'+k,{fact_kind:{'미정':'미정','사실':'사실','원문 해석':'원문 해석','창작자의 각색':'창작자의 각색','AI 제안':'AI 제안'},cost_kind:{'미상':'미상','추정':'추정','수동 입력':'수동 입력','실제 실행':'실제 실행'},adoption_state:{'후보':'후보','시험 중':'시험 중','채택':'채택','중단':'중단'},execution_mode:{'확인 필요':'확인 필요','수동':'수동','API':'API','로컬':'로컬'},media_kind:{'이미지':'이미지','영상':'영상','음성':'음성','음악':'음악','효과음':'효과음','자막':'자막','편집본':'편집본'},job_state:{queued:'대기',running:'실행 중',succeeded:'성공',failed:'실패',cancelled:'취소',interrupted:'중단'}}[k],fields[k]||''):inputField(fieldLabels[k]||k,'field_'+k,fields[k]||'',k==='checked_at'?'date':(['official_url','budget_amount','currency','cost_unit','mime_type','sha256'].includes(k)?'text':'textarea'))).join('')}</div></details>`;}
function reviewForm(action){const r=state.records.find(r=>r.id===selectedId);const label={submit:'검토 요청',approve:'승인하고 완료',reject:'수정 요청'}[action];modal(label,`<p class="prose">${e(r.title)}</p><div class="notice ${action==='approve'?'warning':''}">${action==='approve'?'완료 기준, 체크리스트, 선행 작업을 충족했는지 확인합니다. 승인자와 시각, 이유를 이력에 남깁니다.':action==='reject'?'반려 기준과 필요한 수정 내용을 남겨 다음 작업으로 전달합니다.':'검토자가 지정되어 있어야 합니다. 실행 성공이나 체크 완료는 승인이 아닙니다.'}</div><form id="review-form">${inputField('검토 이유·의견','reason','','textarea','required maxlength="4000"')}<p class="form-error" id="review-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button class="btn primary" type="submit">${label}</button></div></form>`);$('#review-form').onsubmit=async ev=>{ev.preventDefault();const b=$('[type=submit]',ev.target);b.disabled=true;try{await api(`/api/records/${encodeURIComponent(r.id)}/review`,'POST',{revision:r.revision,action,reason:new FormData(ev.target).get('reason')});closeModal();await refresh();toast('검토 이력을 저장했습니다.');}catch(err){$('#review-error').textContent=err.message;b.disabled=false;}};}
function editStage(){const s=state.stages.find(s=>s.id===stageId);const stageOptions={'':'없음',...Object.fromEntries(state.stages.map(x=>[x.id,x.name]))};modal('단계 기준 편집',`<form id="stage-form"><div class="form-grid">${['name','description','input','role','output','criteria','subtasks','recommended_tools'].map(k=>inputField(({name:'단계 이름',description:'설명',input:'입력',role:'담당 역할',output:'출력',criteria:'완료 조건',subtasks:'하위 작업·작업 순서',recommended_tools:'추천 도구 후보·선택 이유'})[k],k,Array.isArray(s[k])?s[k].join('\n'):s[k],k==='name'?'text':'textarea',k==='name'?'required':'')).join('')}${selectField('다음 단계','next',stageOptions,s.next||'')}${selectField('반려·재작업 경로','rework',stageOptions,s.rework||'')}</div><p class="form-error" id="stage-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button type="submit" class="btn primary">기준 저장</button></div></form>`,'',true);$('#stage-form').onsubmit=async ev=>{ev.preventDefault();try{const data=Object.fromEntries(new FormData(ev.target));for(const key of ['subtasks','recommended_tools'])if(Array.isArray(s[key]))data[key]=data[key].split('\n').map(x=>x.trim()).filter(Boolean);data.next=data.next||null;data.rework=data.rework||null;await api('/api/stages/'+encodeURIComponent(s.id),'PATCH',{revision:s.revision,...data});closeModal();await refresh();toast('단계 기준을 저장했습니다.');}catch(err){$('#stage-error').textContent=err.message;}};}
function approveInstructions(){const r=state.records.find(r=>r.id===selectedId);modal('작업 지시 승인',`<p class="prose">${e(r.title)}</p><div class="notice">지시 내용·입력 버전·완료 기준·출력 규격을 확인하고 승인합니다. 이 동작은 최종 결과 승인이나 작업 완료가 아닙니다. 이후 기준을 바꾸면 다시 승인해야 합니다.</div><form id="instructions-form">${inputField('승인 이유','reason','','textarea','required')}<p id="instructions-error" class="form-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button class="btn primary" type="submit">작업 지시 승인</button></div></form>`);$('#instructions-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/records/'+encodeURIComponent(r.id)+'/instructions/approve','POST',{revision:r.revision,reason:new FormData(ev.target).get('reason')});closeModal();await refresh();toast('작업 지시를 승인했습니다. 최종 결과 상태는 유지됩니다.');}catch(err){$('#instructions-error').textContent=err.message;}};}

function newProject(){modal('새 프로젝트 만들기',`<p class="prose">실제 기록이 없는 독립된 프로젝트를 만듭니다. 공정과 양식은 초기 제안으로 제공됩니다.</p><form id="project-form">${inputField('프로젝트 작업명','name','','text','required maxlength="200"')}<p class="form-error" id="project-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button type="submit" class="btn primary">프로젝트 만들기</button></div></form>`);$('#project-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/projects','POST',Object.fromEntries(new FormData(ev.target)));closeModal();page='dashboard';await refresh();toast('새 프로젝트를 만들었습니다.');}catch(err){$('#project-error').textContent=err.message;}};}
function instantiate(id){const t=state.templates.find(t=>t.id===id);modal('양식으로 새 기록 만들기',`<p class="prose">${e(t.title || t.name)} · ${badge('제안 템플릿')}</p><form id="instantiate-form">${inputField('새 기록 제목','title','','text','required maxlength="200"')}<p class="form-help">양식과 기존 기록을 변경하지 않습니다. 새 체크리스트를 독립적으로 만듭니다.</p><p class="form-error" id="instantiate-error" role="alert"></p><div class="modal-form-foot">${btn('취소','close-modal','secondary')}<button class="btn primary" type="submit">복제해서 만들기</button></div></form>`);$('#instantiate-form').onsubmit=async ev=>{ev.preventDefault();try{const r=await api('/api/templates/'+encodeURIComponent(id)+'/instantiate','POST',Object.fromEntries(new FormData(ev.target)));closeModal();state=await api('/api/state');selectedId=r.record?.id || r.id;page='detail';render();toast('독립된 새 기록을 만들었습니다.');}catch(err){$('#instantiate-error').textContent=err.message;}};}
function episodeTree(){const records=activeRecords();const episodes=records.filter(r=>r.type==='episode');const linked=(a,b)=>(a.related_ids||[]).includes(b.id)||(b.related_ids||[]).includes(a.id);modal('회차 → 장면 → 숏 탐색',episodes.length?`<div class="episode-tree">${episodes.map(ep=>`<section><button class="record-title" data-record="${e(ep.id)}">${icon('film')}${e(ep.title)}</button>${records.filter(r=>r.type==='scene'&&linked(ep,r)).map(sc=>`<div class="tree-scene"><button class="text-btn" data-record="${e(sc.id)}">장면 · ${e(sc.title)}</button>${records.filter(r=>r.type==='shot'&&linked(sc,r)).map(sh=>`<div class="tree-shot"><button class="text-btn" data-record="${e(sh.id)}">숏 · ${e(sh.title)}</button></div>`).join('')||'<p class="form-help">연결된 숏 없음</p>'}</div>`).join('')||'<p class="form-help">연결된 장면 없음</p>'}</section>`).join('')}</div>`:empty('등록된 회차가 없습니다.','회차·장면·숏 기록을 만든 뒤 관련 항목으로 서로 연결하세요.','',''),'',true);}
function download(data,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function fileImport(mode){const backup=mode==='backup';modal(backup?'백업 복원':'결과 패키지 가져오기',`<p class="prose">${backup?'복원 전 백업 형식과 포함된 기록을 확인합니다. 현재 프로젝트 변경 사항에 영향을 줄 수 있습니다.':'워크스테이션의 work_result JSON 파일을 선택하세요. 중복·오래된 입력·충돌은 적용 전 표시합니다.'}</p><div class="form-field"><label for="import-file">JSON 파일 선택</label><input id="import-file" type="file" accept=".json,application/json"></div><div id="import-preview"></div><p class="form-error" id="import-error" role="alert"></p>`,btn('닫기','close-modal','secondary'),true);$('#import-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;$('#import-error').textContent='';$('#import-preview').innerHTML='<p>검증 중입니다…</p>';try{if(file.size>10*1024*1024)throw new Error('파일은 10MB 이하여야 합니다.');const data=JSON.parse(await file.text());const result=await api(backup?'/api/backup/preview':'/api/packages/preview','POST',backup?{backup:data}:{package:data});pendingImport={mode,data,result};renderImportPreview();}catch(err){$('#import-preview').innerHTML='';$('#import-error').textContent=err.message;}};}
function renderImportPreview(){const {mode,data,result:r}=pendingImport;const ready=mode==='backup'||r.status==='ready';$('#import-preview').innerHTML=`<div class="notice ${ready?'success':'warning'}"><strong>${mode==='backup'?'백업 검증 완료':({ready:'가져올 수 있습니다',duplicate:'이미 가져온 패키지',conflict:'충돌 · 가져오기 차단',stale:'오래된 입력 · 가져오기 차단'}[r.status]||r.status)}</strong></div><div class="metadata-grid">${Object.entries(r.summary || (mode==='backup'?{project_name:r.project_name,records:r.records,events:r.events}:{})).map(([k,v])=>`<div><span class="detail-label">${e(({job_state:'기술 실행 상태',outputs:'출력 수',task_title:'대상 작업',is_sample:'샘플 여부',run_id:'실행 ID',attempt_id:'시도 ID',records:'기록 수',project_name:'프로젝트',events:'이력 수'})[k]||k)}</span><p>${e(displayFieldValue(k,v))}</p></div>`).join('')}</div>${[...(r.warnings||[]),...(r.reasons||[]),...(r.warning?[r.warning]:[])].map(w=>`<p class="notice warning">${e(w)}</p>`).join('')}<details><summary>패키지 원문 확인</summary><pre class="json-preview">${e(JSON.stringify(data,null,2).slice(0,15000))}</pre></details>${ready?`<div class="modal-form-foot">${btn(mode==='backup'?'확인하고 복원':'확인하고 가져오기',mode==='backup'?'apply-backup':'apply-package','primary','check')}</div>`:'<p class="form-help">데이터를 덮어쓰지 않았습니다. 충돌 원인을 해결한 뒤 새 패키지를 준비하세요.</p>'}`;}
function notionImport(){modal('Notion 내보내기 자료 가져오기',`<div class="notice warning">사용자가 내보낸 파일만 읽습니다. Notion 원본을 직접 변경하지 않습니다. Markdown 한 파일 또는 CSV 한 표씩 가져오세요.</div><form id="notion-form"><div class="form-grid">${selectField('파일 형식','format',{markdown:'Markdown 문서',csv:'CSV 표'},'markdown')}${inputField('원본 Notion 페이지 링크','source_url','','url','required placeholder="https://app.notion.com/p/…"')}${inputField('원본 수정 시각 · 확인한 경우만','source_modified_at','','datetime-local')}<div class="form-field"><label for="notion-file">파일 선택 · 최대 2MB</label><input type="file" id="notion-file" accept=".md,.markdown,.csv,.txt" required></div></div><p class="form-help">읽은 시각은 서버에 저장합니다. 원본 ID를 CSV에 포함하면 재가져오기 때 동일 기록으로 대조합니다. 원본 수정 시각을 확인하지 못했다면 비워 두세요.</p><p class="form-error" id="notion-error" role="alert"></p><button class="btn primary" type="submit">변환·충돌 미리보기</button></form><div id="notion-preview"></div>`,'',true);$('#notion-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target;try{const file=$('#notion-file').files[0];if(file.size>2*1024*1024)throw new Error('파일은 2MB 이하여야 합니다.');const payload={...Object.fromEntries(new FormData(form)),filename:file.name,content:await file.text()};if(payload.source_modified_at)payload.source_modified_at=new Date(payload.source_modified_at).toISOString();else delete payload.source_modified_at;const r=await api('/api/migration/preview','POST',payload);pendingImport={mode:'notion',data:payload,result:r};$('#notion-preview').innerHTML=`<div class="divider"></div><div class="notice ${r.status==='ready'?'success':'warning'}">${e(({ready:'변환 미리보기 · 적용 가능',duplicate:'중복 없음 · 이미 가져온 내용',conflict:'기존 편집과 충돌 · 적용 차단'})[r.status]||r.status)}</div>${(r.items||[]).map(i=>`<div class="activity-row"><div><strong>${e(i.title)}</strong><p>${e(types[i.type]||i.type)} · ${e(({create:'새로 생성',unchanged:'동일함',conflict:'충돌'})[i.action]||i.action)}</p><small>원본 ID: ${e(i.source_id)}</small>${(i.warnings||[]).map(w=>`<p class="form-help">${e(w)}</p>`).join('')}</div></div>`).join('')}${(r.warnings||[]).map(w=>`<p class="notice warning">${e(w)}</p>`).join('')}${r.status==='ready'?btn('확인하고 가져오기','apply-notion','primary','check'):'<p class="form-help">기존 기록을 덮어쓰지 않았습니다.</p>'}`;}catch(err){$('#notion-error').textContent=err.message;}};}
function bindPage(){
 const search=$('#search-input');if(search)search.addEventListener('input',()=>{filters.search=search.value;const records=filteredRecords();$('#records-results').innerHTML=records.length?(listView==='kanban'?kanban(records):recordTable(records)):empty('검색 결과가 없습니다.','검색어나 필터를 변경해 보세요.','','');$('.result-count').textContent=records.length+'개의 기록';});
 for(const key of ['type','category','stage','owner','status']){const field=$('#filter-'+key);if(field)field.onchange=()=>{filters[key]=field.value;render();};}
 const form=$('#settings-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=$('[type=submit]',form);b.disabled=true;try{await api('/api/project','PATCH',{revision:state.project.revision,...Object.fromEntries(new FormData(form))});await refresh();toast('설정을 서버에 저장했습니다.');}catch(err){$('#settings-error').textContent=err.message;b.disabled=false;}};
 const sw=$('#project-switch');if(sw)sw.onchange=async()=>{try{await api('/api/projects/select','POST',{id:sw.value});page='dashboard';await refresh();}catch(err){toast(err.message,true);}};
 for(const input of $$('[data-check]'))input.onchange=async()=>{const r=state.records.find(r=>r.id===selectedId);const checklist=r.checklist.map((c,i)=>({...c,done:i===Number(input.dataset.check)?input.checked:c.done}));try{await api('/api/records/'+encodeURIComponent(r.id),'PATCH',{revision:r.revision,checklist});await refresh();toast('체크 상태를 저장했습니다.');}catch(err){input.checked=!input.checked;toast(err.message,true);}};
 for(const bar of $$('[data-progress]'))bar.style.width=bar.dataset.progress+'%';
}
document.addEventListener('click',async ev=>{
 const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();closeModal();navigate(nav.dataset.nav,nav.dataset.category || '');return;}
 const record=ev.target.closest('[data-record]');if(record){closeModal();selectedId=record.dataset.record;page='detail';render();window.scrollTo(0,0);return;}
 const stage=ev.target.closest('[data-stage]');if(stage){navigate('stage','',stage.dataset.stage);return;}
 const view=ev.target.closest('[data-view]');if(view){listView=view.dataset.view;render();return;}
 const dataView=ev.target.closest('[data-data-view]');if(dataView){filters.sample=dataView.dataset.dataView==='sample';filters.archived=false;render();return;}
 const archive=ev.target.closest('[data-archive]');if(archive){filters.archived=archive.dataset.archive==='true';render();return;}
 const template=ev.target.closest('[data-template]');if(template){instantiate(template.dataset.template);return;}
 const actionButton=ev.target.closest('[data-action]');if(!actionButton)return;const action=actionButton.dataset.action;
 try{
 switch(action){
 case'close-modal':closeModal();break;
 case'menu':$('#sidebar').classList.add('open');$('#mobile-overlay').classList.remove('hidden');$('#mobile-overlay').classList.add('open');break;
 case'close-menu':$('#sidebar').classList.remove('open');$('#mobile-overlay').classList.add('hidden');$('#mobile-overlay').classList.remove('open');break;
 case'logout':await api('/api/logout','POST',{});session=null;state=null;renderLogin();break;
 case'new-record':recordForm();break;
 case'create-category-panel':recordForm(null,'document',{title:cats[category].name+' · 작업 기준',category,purpose:'제안 템플릿: 이 카테고리에서 무엇을 만들고 어떤 기준으로 검토할지 작성합니다. 담당자·검토자·입력 자료와 버전·작업 절차·지시문·완료 기준을 실제 작업에 맞게 채우세요.',fields:{category_panel:category,steps:'제안 절차: 목적 확인 → 입력·선행 조건 확인 → 세부 항목 작성 → 관련 기록 연결 → 체크리스트 확인 → 검토 요청'}});break;
 case'new-task':recordForm(null,'task');break;
 case'new-episode':recordForm(null,'episode');break;
 case'edit-record':recordForm(state.records.find(r=>r.id===selectedId));break;
 case'archive-record':{const r=state.records.find(r=>r.id===selectedId);await api('/api/records/'+encodeURIComponent(r.id),'PATCH',{revision:r.revision,archived:!r.archived});await refresh();toast(r.archived?'보관을 해제했습니다.':'기록을 보관했습니다.');break;}
 case'review-submit':reviewForm('submit');break;
 case'review-approve':reviewForm('approve');break;
 case'review-reject':reviewForm('reject');break;
 case'edit-stage':editStage();break;
 case'new-project':newProject();break;
 case'episode-tree':episodeTree();break;
 case'backup':download(await api('/api/backup'),`animation-backup-${new Date().toISOString().slice(0,10)}.json`);toast('백업 파일을 내려받았습니다.');break;
 case'restore-backup':fileImport('backup');break;
 case'import-package':fileImport('package');break;
 case'copy-instruction':await copyInstruction();break;
 case'approve-instructions':approveInstructions();break;
 case'export-task':{actionButton.disabled=true;const pkg=await api('/api/packages/export','POST',{task_id:selectedId});download(pkg,`work_request-${pkg.package_id || 'v1'}.json`);toast('작업 패키지를 내려받았습니다.');actionButton.disabled=false;break;}
 case'apply-package':{actionButton.disabled=true;try{await api('/api/packages/import','POST',{package:pendingImport.data,fingerprint:pendingImport.result.fingerprint});closeModal();await refresh();toast('결과를 가져왔습니다. 사람의 승인 상태는 유지됩니다.');}catch(err){$('#import-error').textContent=err.message;actionButton.disabled=false;}break;}
 case'apply-backup':{actionButton.disabled=true;try{await api('/api/backup/restore','POST',{backup:pendingImport.data,confirmation:'복원'});closeModal();page='dashboard';await refresh();toast('백업을 복원했습니다.');}catch(err){$('#import-error').textContent=err.message;actionButton.disabled=false;}break;}
 case'import-notion':notionImport();break;
 case'apply-notion':{actionButton.disabled=true;try{const r=await api('/api/migration/import','POST',{...pendingImport.data,fingerprint:pendingImport.result.fingerprint});closeModal();await refresh();toast(`${r.created || 0}개 기록을 가져왔습니다. 원본은 변경하지 않았습니다.`);}catch(err){$('#notion-error').textContent=err.message;actionButton.disabled=false;}break;}
 }
 }catch(err){actionButton.disabled=false;toast(err.message,true);}
});
document.addEventListener('keydown',ev=>{
 const modalEl=$('.modal');if(!modalEl)return;if(ev.key==='Escape'){ev.preventDefault();closeModal();return;}if(ev.key==='Tab'){const els=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],summary',modalEl).filter(el=>el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els[els.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}
});
boot();
